def fix_resize_rc(t):
    m = re.search(r"IDD_SHUICAST DIALOGEX[^\n]*\nSTYLE [^\n]*", t)
    if m is None:
        fail("rc: IDD_SHUICAST STYLE not found")
    if "WS_THICKFRAME" in m.group(0):
        return t
    end = m.end()
    if t[end - 1] == "\r":
        end -= 1
    return t[:end] + " | WS_THICKFRAME | WS_MAXIMIZEBOX" + t[end:]


