        lambda m: m.group(1)
        + "\n    RecalcGeometry();\n}\n\n"
        + "// " + MARK_METER + ": the meter positions are calculated again when the window is resized\n"
        + "void CFlexMeters::RecalcGeometry()\n{\n"
        + "    RECT rect;\n\n    GetClientRect(fmis.hWndFrame, &rect);\n"
