# 10. エンコーダーの削除 (接続チェックを一緒に詰める)
# ----------------------------------------------------------------------

MARK_DELETE = TAG + ": delete"


def _delete_body(m):
    body = m.group(0)
    # the settings window refers to an encoder by its position: close it without applying.
    # The check boxes are kept by row number: move the rows below up by one, like the encoders
    body = sub_once(
        body,
        r"\n([ \t]*)m_Encoders\.DeleteAllItems\(\);",
        lambda m: "\n" + m.group(1) + "/* " + MARK_DELETE + " */\n"
        + m.group(1) + "if (configDialog != NULL && configDialog->GetSafeHwnd() != NULL && configDialog->IsWindowVisible()) {\n"
        + m.group(1) + "\tconfigDialog->ShowWindow(SW_HIDE);\n"
        + m.group(1) + "}\n"
        + m.group(1) + "for (int k = iItem; k < MAX_ENCODERS; k++) {\n"
        + m.group(1) + "\ts_encUnchecked[k] = (k + 1 < gMain.GetNumEncoders() && k + 1 < MAX_ENCODERS) ? s_encUnchecked[k + 1] : false;\n"
        + m.group(1) + "}\n"
        + m.group(0)[1:],
        "OnPopupDelete DeleteAllItems",
    )
    # with MAX_ENCODERS encoders the loop must not read past the end of the array
    return sub_once(body, r"if \( gEncoders\[i \+ 1\] \)", lambda m: "if ( i + 1 < MAX_ENCODERS && gEncoders[i + 1] )", "OnPopupDelete next encoder")


def fix_delete(t):
    if MARK_DELETE in t:
        return t
    return sub_once(t, r"void CMainWindow::OnPopupDelete\s*\(\s*\)(?s:.*?)\n\}\n", _delete_body, "OnPopupDelete")


MARK_ADDLIMIT = TAG + ": addlimit"


def fix_add_limit(t):
    """The encoder arrays hold MAX_ENCODERS (10) entries: refuse to add one more."""
    if MARK_ADDLIMIT in t:
        return t
    guard = (
        "\n\t/* " + MARK_ADDLIMIT + " */\n"
        "\tif (gMain.GetNumEncoders() >= MAX_ENCODERS) {\n"
        '\t\tMessageBox( "You cannot add more than 10 encoders.", "Message", MB_OK );\n'
        "\t\treturn;\n"
        "\t}\n"
    )
    return after(t, r"void CMainWindow::OnAddEncoder\s*\(\s*\)\s*\{", guard, "OnAddEncoder limit")


